func strictResource(data []byte, kind string) (map[string]json.RawMessage, common.JSONSidecar, error) {
	known, sidecar, err := common.DecodeResponseJSONWithSidecar(data, resourceResponseShape(kind))
	if err != nil {
		return nil, nil, err
	}
	fields, err := common.DecodeStrictObject(known, []string{"apiVersion", "kind", "metadata", "spec"}, []string{"apiVersion", "kind", "metadata", "spec"})
	return fields, sidecar, err
}
func strictResourceExact(data []byte) (map[string]json.RawMessage, error) {
	return common.DecodeStrictObject(data, []string{"apiVersion", "kind", "metadata", "spec"}, []string{"apiVersion", "kind", "metadata", "spec"})
}
func strictSpec(raw json.RawMessage, allowed, required []string) (map[string]json.RawMessage, error) {
	return common.DecodeStrictObject(raw, allowed, required)
}
func fieldString(fields map[string]json.RawMessage, name, path string) (string, error) {
	var value string
	if err := json.Unmarshal(fields[name], &value); err != nil {
		return "", common.ContractError("INVALID_FIELD_TYPE", path)
	}
	return value, nil
}
func fieldInt(fields map[string]json.RawMessage, name, path string) (int, error) {
	var value int
	if err := json.Unmarshal(fields[name], &value); err != nil {
		return 0, common.ContractError("INVALID_FIELD_TYPE", path)
	}
	return value, nil
}
func fieldInt64(fields map[string]json.RawMessage, name, path string) (int64, error) {
	var value int64
	if err := json.Unmarshal(fields[name], &value); err != nil {
		return 0, common.ContractError("INVALID_FIELD_TYPE", path)
	}
	return value, nil
}
func fieldStringArray(raw json.RawMessage, path string) ([]string, error) {
	var value []string
	if err := json.Unmarshal(raw, &value); err != nil {
		return nil, common.ContractError("INVALID_FIELD_TYPE", path)
	}
	return value, nil
}
func checkResourceBase(fields map[string]json.RawMessage, expectedKind string) (ResourceBase, error) {
	apiVersion, err := fieldString(fields, "apiVersion", "/apiVersion")
	if err != nil {
		return ResourceBase{}, err
	}
	kind, err := fieldString(fields, "kind", "/kind")
	if err != nil {
		return ResourceBase{}, err
	}
	if apiVersion != APIVersion || kind != expectedKind {
		return ResourceBase{}, common.ContractError("RESOURCE_KIND_MISMATCH", "/kind")
	}
	metadata, err := common.DecodeResourceMetadataJSON(fields["metadata"])
	if err != nil {
		return ResourceBase{}, err
	}
	return ResourceBase{APIVersion: apiVersion, Kind: kind, Metadata: metadata}, nil
}
func checkDisplayState(spec map[string]json.RawMessage, path string, states ...string) (string, string, error) {
	displayName, err := fieldString(spec, "displayName", path+"/displayName")
	if err != nil {
		return "", "", err
	}
	if err := common.ValidateString(displayName, 1, 160, path+"/displayName"); err != nil {
		return "", "", err
	}
	state, err := fieldString(spec, "state", path+"/state")
	if err != nil {
		return "", "", err
	}
	for _, allowed := range states {
		if state == allowed {
			return displayName, state, nil
		}
	}
	return "", "", common.ContractError("INVALID_STATE", path+"/state")
}
func checkTenantMetadata(base ResourceBase, expected common.TenantRef) error {
	if !common.EqualTenantRef(base.Metadata.TenantRef, expected) {
		return common.ContractError("TENANT_AUTHORITY_MISMATCH", "/metadata/tenantRef")
	}
	return nil
}

func DecodePlatformTenantJSON(data []byte) (PlatformTenant, error) {
	fields, err := strictResourceExact(data)
	if err != nil {
		return PlatformTenant{}, err
	}
	base, err := checkResourceBase(fields, "PlatformTenant")
	if err != nil {
		return PlatformTenant{}, err
	}
	spec, err := strictSpec(fields["spec"], []string{"displayName", "state"}, []string{"displayName", "state"})
	if err != nil {
		return PlatformTenant{}, err
	}
	display, state, err := checkDisplayState(spec, "/spec", "active", "suspended")
	if err != nil {
		return PlatformTenant{}, err
	}
	if base.Metadata.UID != base.Metadata.TenantRef.ID || base.Metadata.Name != base.Metadata.TenantRef.ID {
		return PlatformTenant{}, common.ContractError("TENANT_AUTHORITY_MISMATCH", "/metadata")
	}
	return PlatformTenant{ResourceBase: base, Spec: TenantSpec{DisplayName: display, State: state}}, nil
}
func DecodePlatformTenantResponseJSON(data []byte) (common.ResponseEnvelope[PlatformTenant], error) {
	return decodeTenantResponse(data)
}
func decodeTenantResponse(data []byte) (common.ResponseEnvelope[PlatformTenant], error) {
	fields, sidecar, err := strictResource(data, "PlatformTenant")
	if err != nil {
		return common.ResponseEnvelope[PlatformTenant]{}, err
	}
	raw, _ := json.Marshal(fields)
	value, err := DecodePlatformTenantJSON(raw)
	if err != nil {
		return common.ResponseEnvelope[PlatformTenant]{}, err
	}
	return common.ResponseEnvelope[PlatformTenant]{Value: value, Unknown: sidecar}, nil
}
func EncodePlatformTenantResponseJSON(value common.ResponseEnvelope[PlatformTenant]) ([]byte, error) {
	return common.EncodeJSONObjectWithSidecar(value.Value, value.Unknown)
}

func DecodeOrganizationJSON(data []byte) (Organization, error) {
	fields, err := strictResourceExact(data)
	if err != nil {
		return Organization{}, err
	}
	base, err := checkResourceBase(fields, "Organization")
	if err != nil {
		return Organization{}, err
	}
	spec, err := strictSpec(fields["spec"], []string{"tenantRef", "displayName", "state"}, []string{"tenantRef", "displayName", "state"})
	if err != nil {
		return Organization{}, err
	}
	tenant, err := common.DecodeTenantRefJSON(spec["tenantRef"])
	if err != nil {
		return Organization{}, err
	}
	display, state, err := checkDisplayState(spec, "/spec", "active", "suspended")
	if err != nil {
		return Organization{}, err
	}
	if err := checkTenantMetadata(base, tenant); err != nil {
		return Organization{}, err
	}
	return Organization{ResourceBase: base, Spec: OrganizationSpec{TenantRef: tenant, DisplayName: display, State: state}}, nil
}
